import{_ as a,o as e,c as d,a2 as i}from"./chunks/framework.BW2T23B9.js";const f=JSON.parse('{"title":"复习系统","description":"","frontmatter":{},"headers":[],"relativePath":"guide/review-system.md","filePath":"guide/review-system.md","lastUpdated":null}'),r={name:"guide/review-system.md"};function l(o,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="复习系统" tabindex="-1">复习系统 <a class="header-anchor" href="#复习系统" aria-label="Permalink to &quot;复习系统&quot;">​</a></h1><p>复习系统负责从本地状态中选择到期项目、提交评分、更新记忆状态并记录历史。它不负责定义课程内容。</p><h2 id="项目来源" tabindex="-1">项目来源 <a class="header-anchor" href="#项目来源" aria-label="Permalink to &quot;项目来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>调度所有者</th><th>说明</th></tr></thead><tbody><tr><td>课程词汇、表达、语法</td><td>Turna FSRS</td><td>使用 Dart <code>FsrsEngine</code></td></tr><tr><td>Official Anki 卡片</td><td>Official Anki scheduler</td><td>使用 rslib FFI 会话</td></tr><tr><td>错题专项</td><td>错题与课程状态</td><td>可重新组装练习，不替代正式 SRS</td></tr><tr><td>弱词专项</td><td>SRS 与学习证据</td><td>选择稳定度低或近期失败项目</td></tr></tbody></table><p>不同所有者不得在运行时混写同一张卡片的调度状态。Official owner 不可用时应关闭相关复习，而不是静默改用 Turna FSRS。</p><h2 id="队列生命周期" tabindex="-1">队列生命周期 <a class="header-anchor" href="#队列生命周期" aria-label="Permalink to &quot;队列生命周期&quot;">​</a></h2><ol><li>读取当前时间与本地到期状态。</li><li>按来源和配置构造队列。</li><li>展示题目或卡片正面。</li><li>接收二元或四档评分。</li><li>调度器计算新状态和 due。</li><li>在事务边界内写入状态与历史。</li><li>从队列移除或按重学规则重新插入。</li></ol><h2 id="当日重学" tabindex="-1">当日重学 <a class="header-anchor" href="#当日重学" aria-label="Permalink to &quot;当日重学&quot;">​</a></h2><p>失败项目进入短间隔重学。默认短步进为 10 分钟。当日失败次数达到 <code>maxSameDayFails</code> 后，due 推迟到次日，避免在单日内无限循环同一项目。</p><h2 id="撤销" tabindex="-1">撤销 <a class="header-anchor" href="#撤销" aria-label="Permalink to &quot;撤销&quot;">​</a></h2><p>撤销依赖上一条复习历史和评分前状态。评分写入期间，该项目处于 in-flight 状态，不接受并发撤销。写入完成后才允许恢复。</p><h2 id="同胞卡" tabindex="-1">同胞卡 <a class="header-anchor" href="#同胞卡" aria-label="Permalink to &quot;同胞卡&quot;">​</a></h2><p>Anki 同一 note 生成的多张 card 可以按 <code>importId + noteId</code> 归组。设置允许分别隐藏同日新卡和同日复习卡。该策略减少答案泄漏，不删除卡片。</p><h2 id="难卡" tabindex="-1">难卡 <a class="header-anchor" href="#难卡" aria-label="Permalink to &quot;难卡&quot;">​</a></h2><p>失败阈值可配置为 2–20 次。达到阈值后可执行：</p><ul><li>仅标记和提醒。</li><li>进入难卡专项视图。</li><li>自动暂停。</li></ul><p>默认阈值为 5 次，默认不自动暂停。</p><h2 id="队列异常" tabindex="-1">队列异常 <a class="header-anchor" href="#队列异常" aria-label="Permalink to &quot;队列异常&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>检查</th></tr></thead><tbody><tr><td>今日无卡</td><td>检查系统时间、目标课程、due 与筛选规则</td></tr><tr><td>同一卡重复出现</td><td>检查重学阶梯和提交事务是否成功</td></tr><tr><td>Anki 评分不更新</td><td>检查 Official runtime 与 owner</td></tr><tr><td>撤销不可用</td><td>等待在途评分完成，检查历史是否存在</td></tr><tr><td>新卡过多</td><td>调整新卡顺序、上限或同胞卡规则</td></tr></tbody></table><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/fsrs">FSRS 复习</a></li><li><a href="/docs/guide/memory-state">记忆状态与评分</a></li><li><a href="/docs/guide/mistakes-and-weak-items">错题与弱项</a></li></ul>',21)])])}const m=a(r,[["render",l]]);export{f as __pageData,m as default};
